package com.example.customcompose.model

data class SurveyDataModel(
    val type: String,
    val group: String,
    val blocks: List<Block>
)

data class Block(
    val id: String,
    val skip: Skip?,
    val type: String,
    val options: List<Option>?,
    val referTo: ReferTo?,
    val question: Question,
    val required: Boolean,
    val validations: Validations?
)

data class Skip(
    val id: String,
    val group_no: String
)

data class Option(
    val value: String,
    val referTo: ReferTo?
)

data class ReferTo(
    val id: String,
    val group_no: String
)

data class Question(
    val slug: String,
    val alias: String
)

data class Validations(
    val regex: String?,
    val terms: List<String>?,
    val bypass: Boolean?,
    val device: Boolean?,
    val server: Boolean?
)

data class JumpingLogic(
    val id: String,
    val group_no: String,
    val conditions: List<String>
)


